import bpy,json,math,hashlib,numpy as np
from pathlib import Path
from mathutils import Vector,Matrix
root=Path(bpy.data.filepath).parent.parent;cap=root/'captures/coastal_environment_20261116'
assert 'ENV16_Craft' not in bpy.data.collections
# Read-only inventory and preservation snapshot.
def digest(o):
 h=hashlib.sha256();h.update(np.array(o.matrix_world,dtype=np.float64).tobytes());h.update(str([(m.name if m else '') for m in o.data.materials]).encode())
 for field,items,width,dtype in [('co',o.data.vertices,3,np.float32),('vertices',o.data.loops,1,np.int32)]:
  if field=='vertices':field='vertex_index'
  a=np.empty(len(items)*width,dtype);items.foreach_get(field,a);h.update(a.tobytes())
 for uv in o.data.uv_layers:
  a=np.empty(len(uv.data)*2,np.float32);uv.data.foreach_get('uv',a);h.update(a.tobytes())
 a=np.empty(len(o.data.polygons),np.int32);o.data.polygons.foreach_get('material_index',a);h.update(a.tobytes())
 return h.hexdigest()
before={o.name:digest(o) for o in bpy.data.objects if o.type=='MESH'}
(cap/'source_before.json').write_text(json.dumps(before),encoding='utf8')
ns=dict(bpy=bpy,json=json,math=math,np=np,Path=Path,Vector=Vector,Matrix=Matrix,root=root,cap=cap,digest=digest,before=before)
bpy.app.driver_namespace['env16']=ns
for cn in ['Coast_CraftWarehouse','Shipyard_COMBINED_Craft','Pier_Working']:
 c=bpy.data.collections[cn];found=[]
 for o in c.objects:
  if o.type=='MESH' and any(k in o.name.lower() for k in ['post','frame','plank','barrel','crate','box','rope','bush','leaf']):
   found.append({'name':o.name,'size':[round(v,3) for v in o.dimensions],'mats':[m.name for m in o.data.materials]})
 print(cn,found[:22])
print('ENV16_BASELINE',len(before),'mesh objects preserved')
